import asyncio
import json
import os
from datetime import datetime
from zoneinfo import ZoneInfo

from telethon import TelegramClient, events
from telethon.errors import FloodWaitError
from telethon.sessions import StringSession

# Create the Telegram client before registering event handlers.

# ============================== CONFIG ======================================

API_ID = int(os.environ.get("API_ID", "0"))
API_HASH = os.environ.get("API_HASH", "")
STRING_SESSION = os.environ.get("STRING_SESSION", "")
client = TelegramClient(
    StringSession(STRING_SESSION),
    API_ID,
    API_HASH,
)

INTERVAL_SECONDS = int(os.environ.get("INTERVAL_SECONDS", "300"))  # 5 minutes
START_HOUR = int(os.environ.get("START_HOUR", "7"))
END_HOUR = int(os.environ.get("END_HOUR", "23"))
TIMEZONE = os.environ.get("TIMEZONE", "Asia/Kolkata")
GAP_BETWEEN_GROUPS = float(os.environ.get("GAP_BETWEEN_GROUPS", "2"))

# Put your own image in the project folder with this name.
PHOTO_PATH = os.environ.get("PHOTO_PATH", "photo.jpg")
PHOTO_BASE64 = """"""
PHOTO_BASE64_SECOND = """"""
PHOTO_BASE64_THIRD = """"""

# The link used in the DM flow.
DM_LINK = os.environ.get(
    "DM_LINK",
    "https://t.me/Seven7BETOfficial_bot?start=7321525865",
)

# ============================== DM FLOW =====================================

DM_STEPS = {
    0: "hello 🤗",
    1: "Koi mera channel join karega to me Apnii bubu dikha dungiii😁😁🤭🤭",
    2: DM_LINK,
    3: "__PHOTO__",
    4: "__PHOTO_SECOND__",
    5: "Join karo channel 😚",
    6: "Screenshot dikhao",
    7: DM_LINK,
    8: "👉 Dubara dabao isko",
}

DM_STATE_FILE = "dm_state.json"


def load_dm_state():
    try:
        with open(DM_STATE_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
            return {str(k): int(v) for k, v in data.items()}
    except (FileNotFoundError, json.JSONDecodeError, TypeError, ValueError):
        return {}


def save_dm_state(state):
    try:
        with open(DM_STATE_FILE, "w", encoding="utf-8") as f:
            json.dump(state, f)
    except Exception as e:
        print(f"Could not save {DM_STATE_FILE}: {e}")


dm_state = load_dm_state()

# Prevent two rapid messages from the same user from racing the shared state.
dm_locks = {}
# Serialize outgoing DM sends so a large burst of users cannot race Telegram
# requests against each other. Each send is retried until it succeeds.
dm_send_lock = asyncio.Lock()

def get_dm_lock(user_id):
    key = str(user_id)
    lock = dm_locks.get(key)
    if lock is None:
        lock = asyncio.Lock()
        dm_locks[key] = lock
    return lock


async def send_dm_step(event, user_id):
    """Send the current DM step. Never advance state until Telegram confirms success."""
    key = str(user_id)

    while True:
        step = dm_state.get(key, 0)
        if step >= len(DM_STEPS):
            return True

        content = DM_STEPS[step]

        try:
            # One outgoing DM at a time. This prevents a burst of users from
            # creating competing requests and makes FloodWait handling predictable.
            async with dm_send_lock:
                if content in ("__PHOTO__", "__PHOTO_SECOND__", "__PHOTO_THIRD__"):
                    import base64
                    import io
                    selected_b64 = (
                        PHOTO_BASE64
                        if content == "__PHOTO__"
                        else PHOTO_BASE64_SECOND
                        if content == "__PHOTO_SECOND__"
                        else PHOTO_BASE64_THIRD
                    )
                    if selected_b64:
                        photo_bytes = base64.b64decode(selected_b64)
                        photo_file = io.BytesIO(photo_bytes)
                        photo_file.name = "photo.jpg"
                        await client.send_file(event.chat_id, photo_file, force_document=False)
                    elif os.path.isfile(PHOTO_PATH):
                        await client.send_file(event.chat_id, PHOTO_PATH, force_document=False)
                    else:
                        raise FileNotFoundError(
                            "Photo unavailable: set the correct PHOTO_BASE64 value or PHOTO_PATH."
                        )
                else:
                    await client.send_message(event.chat_id, content, parse_mode="md")

            # Only after a confirmed successful send do we advance the state.
            dm_state[key] = step + 1
            save_dm_state(dm_state)
            print(f"DM step {step} sent to user {user_id}.")
            return True

        except FloodWaitError as e:
            wait = max(1, int(getattr(e, "seconds", 1))) + 1
            print(f"FloodWait for user {user_id}: waiting {wait}s before retrying step {step}.")
            await asyncio.sleep(wait)
        except Exception as e:
            # Do not give up after a fixed number of attempts. Keep the step
            # pending and retry with increasing delay so the flow can resume
            # automatically even during temporary Telegram/network failures.
            print(f"DM step {step} failed for user {user_id}: {e}; retrying.")
            await asyncio.sleep(min(60, 2 + (step % 5) * 2))


async def finish_dm_stage(event, user_id):
    """Resume a partially completed stage and finish it without needing another user message."""
    key = str(user_id)
    step = dm_state.get(key, 0)

    # 0, 1 are single-message stages.
    if step in (0, 1):
        await send_dm_step(event, user_id)
        return

    # Link -> photo 1 -> photo 2 -> join text -> screenshot prompt.
    if 2 <= step <= 6:
        target = 6
    # Final link + plain text message (no attached/clickable link).
    elif step == 7:
        target = 8
    else:
        return

    while dm_state.get(key, 0) <= target:
        await send_dm_step(event, user_id)


@client.on(events.NewMessage(incoming=True))
async def dm_handler(event):
    if event.out or not event.is_private:
        return

    sender = await event.get_sender()
    if sender is None or getattr(sender, "bot", False):
        return

    user_id = sender.id
    lock = get_dm_lock(user_id)
    async with lock:
        await finish_dm_stage(event, user_id)


# ============================== GROUP FLOW ==================================

GROUP_MESSAGES = [
    "Hello koi merii chuttt dekhegaaa free me😘😘",
    "koi marlo meri thukai krdo💦!",
    "koi meri boobss dekhega 😘😘🤤🤤",
    "nangii hunn dekhne ke liye dmm kroo",
]
group_message_index = 0


def is_within_active_hours() -> bool:
    now = datetime.now(ZoneInfo(TIMEZONE))
    return START_HOUR <= now.hour < END_HOUR


async def get_authorized_group_ids():
    """
    If GROUP_IDS is configured, keep the original behavior and use those IDs.

    If GROUP_IDS is empty, automatically discover groups that the logged-in
    Telegram account is already a member of. No username or manually entered
    group ID is required.
    """
    raw = os.environ.get("GROUP_IDS", "").strip()

    # Keep the original explicit GROUP_IDS option unchanged.
    if raw:
        group_ids = []
        for value in raw.split(","):
            value = value.strip()
            if not value:
                continue
            try:
                group_ids.append(int(value))
            except ValueError:
                print(f"Invalid GROUP_IDS value ignored: {value}")
        return group_ids

    # New fallback: discover groups from the logged-in account's dialogs.
    groups = []
    async for dialog in client.iter_dialogs():
        entity = dialog.entity
        if getattr(entity, "megagroup", False) or getattr(entity, "gigagroup", False):
            groups.append(dialog.id)

    print(f"Auto-detected {len(groups)} joined group(s).")
    return groups


async def broadcast_once():
    global group_message_index

    groups = await get_authorized_group_ids()

    if not groups:
        print("No joined groups found; skipping group broadcast.")
        return

    message = GROUP_MESSAGES[group_message_index]
    group_message_index = (group_message_index + 1) % len(GROUP_MESSAGES)

    sent = 0

    for chat_id in groups:
        try:
            await client.send_message(chat_id, message)
            sent += 1
        except Exception as e:
            print(f"Failed to send to group {chat_id}: {e}")

        await asyncio.sleep(GAP_BETWEEN_GROUPS)

    print(f"Sent '{message}' to {sent}/{len(groups)} authorized groups.")


async def broadcast_loop():
    while True:
        if is_within_active_hours():
            await broadcast_once()
        else:
            now = datetime.now(ZoneInfo(TIMEZONE))
            print(
                f"Outside active hours "
                f"({now.strftime('%H:%M')} {TIMEZONE}), "
                "skipping this cycle."
            )

        await asyncio.sleep(INTERVAL_SECONDS)


# ============================== RUN =========================================

async def run():
    await client.start()

    me = await client.get_me()

    print(f"Logged in as {me.first_name}")
    print(
        f"Group messages rotate every {INTERVAL_SECONDS}s "
        f"between {START_HOUR}:00 and {END_HOUR}:00 ({TIMEZONE})."
    )
    print("DM flow enabled.")
    print("Photo is embedded in code.")

    await broadcast_loop()


if __name__ == "__main__":
    missing = []

    if not API_ID:
        missing.append("API_ID")

    if not API_HASH:
        missing.append("API_HASH")

    if not STRING_SESSION.strip():
        missing.append("STRING_SESSION")

    if missing:
        print(
            f"Missing environment variables: {', '.join(missing)}"
        )
        print(
            "Railway Variables me API_ID, API_HASH aur STRING_SESSION set karein."
        )
    else:
        print("Userbot starting...")
        client.loop.run_until_complete(run())
